async function runBoundedParallelScan(symbols, workerFn, concurrency = 6, timeoutMs = 6500) {
  const results = [];
  const queue = [...symbols];
  let activeWorkers = 0;
  return new Promise((resolve) => {
    if (queue.length === 0) {
      return resolve([]);
    }
    const next = () => {
      while (activeWorkers < concurrency && queue.length > 0) {
        const symbol = queue.shift();
        if (!symbol) break;
        activeWorkers++;
        let timer = null;
        const timeoutPromise = new Promise((_, reject) => {
          timer = setTimeout(() => {
            reject(new Error(`Worker scan timeout after ${timeoutMs}ms for ${symbol}`));
          }, timeoutMs);
        });
        Promise.race([
          workerFn(symbol).finally(() => {
            if (timer) clearTimeout(timer);
          }),
          timeoutPromise
        ]).then((res) => {
          if (res !== null && res !== void 0) {
            results.push(res);
          }
        }).catch((err) => {
          console.warn(`[MarketUniverse] Isolated failure scanning ${symbol}:`, err?.message || err);
        }).finally(() => {
          activeWorkers--;
          if (queue.length > 0) {
            next();
          } else if (activeWorkers === 0) {
            resolve(results);
          }
        });
      }
    };
    next();
  });
}

