function calculateNewsFreshness(publishedAt, now = Date.now()) {
  const ageMs = Math.max(0, now - publishedAt);
  const ageMinutes = Math.round(ageMs / (60 * 1e3));
  const ageHours = ageMinutes / 60;
  let freshness = "HISTORICAL";
  let decayMultiplier = 0.2;
  let isActive = false;
  if (ageHours < 2) {
    freshness = "BREAKING";
    decayMultiplier = 1;
    isActive = true;
  } else if (ageHours < 8) {
    freshness = "FRESH";
    decayMultiplier = 0.85;
    isActive = true;
  } else if (ageHours < 24) {
    freshness = "RECENT";
    decayMultiplier = 0.7;
    isActive = true;
  } else if (ageHours < 72) {
    freshness = "AGING";
    decayMultiplier = 0.45;
    isActive = true;
  } else {
    freshness = "HISTORICAL";
    decayMultiplier = 0.2;
    isActive = false;
  }
  return {
    freshness,
    ageMinutes,
    decayMultiplier,
    isActive
  };
}
function calculateNewsImpactScore(params) {
  const {
    eventType,
    sentiment,
    sourceTier,
    isVerified,
    sourceCount,
    isDirectTarget,
    freshnessDecay,
    severity
  } = params;
  if (sentiment === "UNKNOWN") {
    return { score: 0, level: "UNKNOWN" };
  }
  let baseScore = severity || 50;
  let tierMultiplier = 1;
  if (sourceTier === "TIER_1") tierMultiplier = 1.25;
  else if (sourceTier === "TIER_2") tierMultiplier = 1.05;
  else if (sourceTier === "TIER_3") tierMultiplier = 0.85;
  else if (sourceTier === "TIER_4") tierMultiplier = 0.5;
  if (!isVerified) {
    tierMultiplier = Math.min(tierMultiplier, 0.55);
  }
  const confirmationBoost = Math.min(1.25, 1 + Math.max(0, sourceCount - 1) * 0.04);
  const directnessMultiplier = isDirectTarget ? 1.15 : 0.85;
  const rawScore = baseScore * tierMultiplier * confirmationBoost * directnessMultiplier;
  const finalScore = Math.min(100, Math.max(10, Math.round(rawScore * freshnessDecay)));
  let level = "LOW";
  if (finalScore >= 80) level = "VERY_HIGH";
  else if (finalScore >= 65) level = "HIGH";
  else if (finalScore >= 45) level = "MEDIUM";
  else level = "LOW";
  return { score: finalScore, level };
}
