  if (dataQualityRating === "INVALID") return "WAIT";
  if (confidence >= 80 && primaryConfirmationsCount >= 2 && dataQualityRating === "HIGH" && riskRewardRatio >= 2 && adversarialVerdict === "APPROVED") {
    return "A+";
  }
  if (confidence >= 70 && primaryConfirmationsCount >= 2 && (dataQualityRating === "HIGH" || dataQualityRating === "MEDIUM") && riskRewardRatio >= 1.8) {
    return "A";
  }
  if (confidence >= 60 && primaryConfirmationsCount >= 1 && riskRewardRatio >= 1.5) {
    return "B";
  }
  if (confidence >= 45) {
    return "C";
  }
  return "WAIT";
