async function sendRawTelegramPhoto(imageBuffer, fileName, caption) {
  const token = runtimeConfig.botToken || process.env.TELEGRAM_BOT_TOKEN;
  const chatId = runtimeConfig.chatId || process.env.TELEGRAM_CHAT_ID;
  if (!token || !chatId) {
    return {
      success: false,
      error: "TELEGRAM_CONFIG_MISSING"
    };
  }
  try {
    const formData = new FormData();
    formData.append("chat_id", chatId);
    formData.append("caption", caption);
    formData.append("parse_mode", "HTML");
    const imageBlob = new Blob([imageBuffer], { type: "image/png" });
    formData.append("photo", imageBlob, fileName);
    const url = `https://api.telegram.org/bot${token}/sendPhoto`;
    const response = await fetch(url, {
      method: "POST",
      body: formData
    });
    const httpStatusCode = response.status;
    if (!response.ok) {
      const errText = await response.text();
      console.warn(`[Telegram] sendPhoto upload failed (HTTP ${httpStatusCode}): ${errText}`);
      return { success: false, httpStatusCode, error: `Telegram sendPhoto failed (${httpStatusCode}): ${errText}` };
    }
    return { success: true, httpStatusCode };
  } catch (err) {
    console.warn("[Telegram] sendPhoto network error:", err?.message);
    return { success: false, error: err?.message || "sendPhoto network failure" };
  }
}
